1051		\notready
1052		\uses{def:polyfunc, def:line, def:ideg-deg-polynomials}
1053		For $f, g \in \mathrm{ideg}_{d,m}(\F_q)$, the polynomial
1054		$\mathrm{combine}_{f,g} \in \mathrm{ideg}_{d,2m+2}(\F_q)$ is defined by
1055		\[
1056			\mathrm{combine}_{f,g}(x, z, \alpha, \beta)
1057			= \alpha f(x) + \beta g(z)\,,
1058			\qquad x \in \F_q^m,\ z \in \F_q^m,\ \alpha \in \F_q,\
1059			\beta \in \F_q\,.
1060		\]
1061		The combining map is also defined for polynomials restricted to lines.
1062		Let $\ell$ be a line in $\F_q^{2m+2}$ with intercept
1063		$u = (u_X, u_Z, u_\alpha, u_\beta)$ and slope
1064		$v = (v_X, v_Z, v_\alpha, v_\beta)$, and let $\ell_X$ and $\ell_Z$ be
1065		lines in $\F_q^m$ such that for every point
1066		$(x, z, \alpha, \beta) \in \ell$ it holds that $x \in \ell_X$ and
1067		$z \in \ell_Z$. Then for any two polynomials
1068		$f \in \deg_{md}(\ell_X)$ and $g \in \deg_{md}(\ell_Z)$, the polynomial
1069		$\mathrm{combine}_{f,g} \in \deg_{md+1}(\ell)$ is defined by
1070		\begin{equation}
1071			\label{eq:combine-lines}
1072			\mathrm{combine}_{f,g}(u + t \cdot v)
1073			= (u_\alpha + t \cdot v_\alpha)\, f(u_X + t \cdot v_X)
1074			+ (u_\beta + t \cdot v_\beta)\, g(u_Z + t \cdot v_Z)\,,
1075			\qquad t \in \F_q\,.
1076		\end{equation}
1077		The degree bound holds because $f$ and $g$, restricted to lines, are
1078		polynomials of degree at most $md$ in the line parameter, and each is
1079		multiplied by an affine factor of degree at most one.
1080	\end{definition}
